import {escapeHtml as esc} from './components.js';
import {safeLink,updated} from './research-view.js';
export const opinionGroup=rating=>/^(매수|비중확대|buy|outperform|overweight)$/i.test(rating||'')?'buy':/^(중립|보유|hold|neutral|equal[ -]weight)$/i.test(rating||'')?'hold':/^(매도|비중축소|sell|underperform|underweight)$/i.test(rating||'')?'sell':'unknown';
const n=v=>Number.isFinite(v)?v.toLocaleString('ko-KR',{maximumFractionDigits:2}):'—';
const ratingLabel=v=>({buy:'매수 (Buy)',hold:'보유 (Hold)',sell:'매도 (Sell)',neutral:'중립 (Neutral)',overweight:'비중확대 (Overweight)',underweight:'비중축소 (Underweight)'}[String(v||'').toLowerCase()]||v||'의견 미기재');
const revision={up:'상향',down:'하향',unchanged:'유지',new:'신규'};
export function analystTargetText(a){if(!a?.target)return '목표주가 미기재';const t=a.target,old=a.previousTarget;if(old&&old.currency===t.currency){const delta=t.value-old.value;return n(old.value)+' → '+n(t.value)+' '+t.currency+' · '+(delta>0?'+':'')+n(delta)+' '+t.currency+(old.value>0?' ('+(delta>0?'+':'')+n(delta/old.value*100)+'%)':'');}return n(t.value)+' '+t.currency+' · '+(a.targetNew?'목표주가 신규 제시':'이전 값 미확인');}
export function mountAnalystOpinions(root,{navigate}){
 let reports=[],rating='all',target='all',coverage=null;const abort=new AbortController(),signal=abort.signal;
 function render(){const list=reports.filter(r=>(rating==='all'||opinionGroup(r.analyst?.rating)===rating)&&(target==='all'||(r.analyst?.targetRevision||r.analyst?.targetRevisionExplicit)===target)).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.postedAt||'').localeCompare(a.postedAt||''));
  root.innerHTML=`<div class="research-heading"><div><h2>증권사 의견 <small>${list.length}건</small></h2><p>수집된 리포트의 명시된 의견 · 전체 시장 컨센서스가 아닙니다.</p></div></div><div class="analyst-filters"><label>투자의견 <select data-analyst-rating aria-label="증권사 투자의견 필터"><option value="all">전체</option><option value="buy">매수</option><option value="hold">중립·보유</option><option value="sell">매도</option></select></label><label>목표주가 <select data-analyst-target aria-label="목표주가 변경 필터"><option value="all">전체</option><option value="up">상향</option><option value="down">하향</option></select></label></div>${list.length?`<table class="research-table analyst-table"><thead><tr><th>발행일</th><th>증권사</th><th>투자의견 및 변경</th><th>목표주가 및 변경</th><th>원문</th></tr></thead><tbody>${list.map(r=>{const a=r.analyst||{},href='/reports?report='+encodeURIComponent(r.id);return `<tr tabindex="0" data-analyst-report="${esc(r.id)}" aria-label="${esc(r.broker||'증권사 미확인')} ${esc(r.date||'발행일 미확인')} 리포트 상세"><td data-label="발행일">${esc(r.date||'발행일 미확인')}<small>${!r.date?'게시 '+esc(updated(r.postedAt)):''}</small></td><td data-label="증권사">${esc(r.broker||'증권사 미확인')}<small>${esc(r.title)}</small></td><td data-label="투자의견 및 변경">${esc(ratingLabel(a.rating))}<small>${esc(revision[a.ratingRevision]||'의견 변경 미기재')}</small></td><td data-label="목표주가 및 변경">${esc(analystTargetText(a))}${a.targetRevision?`<small class="report-target-${a.targetRevision}">목표주가 ${revision[a.targetRevision]}</small>`:''}${!a.previousTarget&&a.targetRevisionExplicit&&!a.targetNew?`<small>보고서 표현: ${esc(revision[a.targetRevisionExplicit])} · 금액 비교 불가</small>`:''}</td><td data-label="원문"><a data-nav href="${href}">리포트 열기 ↗</a><details><summary>추출 근거·출처</summary>${(a.evidence||[]).length?a.evidence.map(e=>`<blockquote>${esc(e.text)}</blockquote>`).join(''):'<p>검증된 추출 근거가 없습니다.</p>'}${(r.sources||[]).map(s=>`<a target="_blank" rel="noopener noreferrer" href="${safeLink(s.url)}">${esc(s.name||'수집 출처')} ↗</a>`).join('')}<p>수집 ${esc(updated(r.collectedAt))}</p></details></td></tr>`;}).join('')}</tbody></table>`:`<p class="research-empty">${reports.length?'선택한 조건에 해당하는 리포트가 없습니다.':'종목 식별자가 확인된 수집 리포트가 없습니다.'}</p>`}<p class="research-note">상향·하향 필터는 원문 표기 또는 확인된 금액 비교 기준입니다. 증감액·증감률은 원문에 이전 금액과 통화가 확인될 때만 계산합니다. 매수·중립·매도 필터에는 명시된 비중확대·비중축소 등 해당 의견군이 포함됩니다. ${esc(coverage?.message||'')}</p>`;
  root.querySelector('[data-analyst-rating]').value=rating;root.querySelector('[data-analyst-target]').value=target;
 }
 root.addEventListener('change',e=>{if(e.target.matches('[data-analyst-rating]'))rating=e.target.value;if(e.target.matches('[data-analyst-target]'))target=e.target.value;render();},{signal});
 root.addEventListener('click',e=>{if(e.target.closest('a,button,details,select'))return;const row=e.target.closest('[data-analyst-report]');if(row)navigate('/reports?report='+encodeURIComponent(row.dataset.analystReport));},{signal});
 root.addEventListener('keydown',e=>{if(e.target.matches('[data-analyst-report]')&&e.key==='Enter'){e.preventDefault();navigate('/reports?report='+encodeURIComponent(e.target.dataset.analystReport));}},{signal});
 render();return {set(rows,status){reports=rows||[];coverage=status;render();},destroy(){abort.abort();}};
}
